-- CT-02j media review + private-to-public promotion. STAGED ONLY.
-- Filename generated by Supabase CLI 3.2.0, GitHub Actions 45309261926.
-- Requires CT-02b/c/e/f/g/h/i, actual staff grants, verified backup and
-- approved release. NO SQL has been applied to hosted Clear Talks.
begin;

alter table public.media_private_drafts
  add column state text not null default 'pending'
    check (state in ('pending','publishing','published','rejected','failed')),
  add column source_sha256 text
    check (source_sha256 is null or source_sha256 ~ '^[0-9a-f]{64}$'),
  add column publication_path text unique,
  add column published_media_id uuid unique references public.media_assets(id),
  add column reviewed_by uuid references auth.users(id),
  add column reviewed_at timestamptz,
  add column review_reason text,
  add column rights_status text,
  add column rights_notes text,
  add column license_name text,
  add column credit text,
  add column license_expires_at timestamptz,
  add column embargo_until timestamptz,
  add column publication_started_at timestamptz,
  add column attempt_count integer not null default 0 check (attempt_count>=0),
  add column last_error text,
  add constraint ct02j_published_has_asset check (
    state <> 'published' or (published_media_id is not null and publication_path is not null)
  );

-- Existing staging rows from CT-02i remain pending; reviewer cannot promote
-- an old draft without an independently verified SHA-256 fingerprint.
create index ct02j_media_private_draft_review_queue
on public.media_private_drafts(state,created_at desc);

grant update on public.media_private_drafts to authenticated;
create policy ct02j_private_review_update
on public.media_private_drafts for update to authenticated using (
  newsroom_private.has_staff_permission('media.approve')
  and newsroom_private.has_staff_permission('media.edit_all')
) with check (
  newsroom_private.has_staff_permission('media.approve')
  and newsroom_private.has_staff_permission('media.edit_all')
);

-- All state transitions are checked in PostgreSQL so direct PostgREST
-- updates cannot publish a draft by bypassing a Next.js route.
create function newsroom_private.guard_private_media_review()
returns trigger language plpgsql security invoker set search_path = ''
as $fn$
declare
  v_extension text;
begin
  if current_user <> 'authenticated' then return new; end if;

  if new.id is distinct from old.id
    or new.uploaded_by is distinct from old.uploaded_by
    or new.bucket_id is distinct from old.bucket_id
    or new.storage_path is distinct from old.storage_path
    or new.file_name is distinct from old.file_name
    or new.mime_type is distinct from old.mime_type
    or new.file_size_bytes is distinct from old.file_size_bytes
    or new.created_at is distinct from old.created_at
    or new.source_sha256 is distinct from old.source_sha256 then
    raise exception 'Original draft file identity is immutable'
      using errcode = '42501';
  end if;

  if not (
    newsroom_private.has_staff_permission('media.approve')
    and newsroom_private.has_staff_permission('media.edit_all')
  ) or new.reviewed_by is distinct from (select auth.uid()) then
    raise exception 'Independent current media review grant required'
      using errcode = '42501';
  end if;
  if old.state in ('published','rejected') then
    raise exception 'Completed review records are immutable'
      using errcode = '42501';
  end if;

  v_extension := case new.mime_type
    when 'image/jpeg' then 'jpg' when 'image/png' then 'png'
    when 'image/webp' then 'webp' when 'image/gif' then 'gif'
    when 'image/avif' then 'avif' else null end;

  if old.state='pending' and new.state='rejected' then
    if char_length(btrim(coalesce(new.review_reason,'')))<8
      or new.reviewed_at is null
      or new.publication_path is not null
      or new.published_media_id is not null
      or new.attempt_count<>old.attempt_count then
      raise exception 'Rejection must have a recorded reason, without publication'
        using errcode = '42501';
    end if;
    return new;
  end if;

  if new.state='publishing' and (
    old.state in ('pending','failed')
    or (old.state='publishing'
      and old.publication_started_at < now()-interval '15 minutes')
  ) then
    if new.source_sha256 is null or v_extension is null
      or new.publication_path is distinct from
        ('approved/' || new.id::text || '.' || v_extension)
      or new.published_media_id is not null
      or new.reviewed_at is null
      or new.publication_started_at is null
      or new.attempt_count<>old.attempt_count+1
      or char_length(btrim(coalesce(new.rights_notes,'')))<10
      or new.rights_status not in (
        'owned','staff_created','licensed','public_domain','creative_commons'
      )
      or (new.rights_status in ('licensed','creative_commons')
        and (nullif(btrim(coalesce(new.license_name,'')),'') is null
          or nullif(btrim(coalesce(new.credit,'')),'') is null))
      or (new.embargo_until is not null and new.embargo_until>now())
      or (new.license_expires_at is not null and new.license_expires_at<=now())
    then
      raise exception 'Media rights, fingerprint and publication claim are incomplete'
        using errcode = '42501';
    end if;
    if old.state<>'pending' and (
      new.publication_path is distinct from old.publication_path
      or new.rights_status is distinct from old.rights_status
      or new.rights_notes is distinct from old.rights_notes
      or new.license_name is distinct from old.license_name
      or new.credit is distinct from old.credit
      or new.license_expires_at is distinct from old.license_expires_at
      or new.embargo_until is distinct from old.embargo_until
    ) then
      raise exception 'Rights and destination are locked after first review'
        using errcode='42501';
    end if;
    return new;
  end if;

  if old.state='publishing' and new.state='failed' then
    if new.publication_path is distinct from old.publication_path
       or new.attempt_count<>old.attempt_count
       or new.reviewed_by is distinct from old.reviewed_by
       or nullif(btrim(coalesce(new.last_error,'')),'') is null then
      raise exception 'Invalid publication failure record'
        using errcode='42501';
    end if;
    return new;
  end if;

  if old.state='publishing' and new.state='published' then
    if new.attempt_count<>old.attempt_count
      or new.publication_path is distinct from old.publication_path
      or new.reviewed_by is distinct from old.reviewed_by
      or new.published_media_id is null
      or not exists (
        select 1 from public.media_assets m
        where m.id=new.published_media_id
          and m.storage_path=new.publication_path
          and m.status='approved'
          and m.approved_by=(select auth.uid())
          and m.uploaded_by=(select auth.uid())
          and m.rights_status::text=new.rights_status
      )
    then
      raise exception 'A verified approved public asset is required'
        using errcode='42501';
    end if;
    return new;
  end if;

  raise exception 'Private media review state transition denied'
    using errcode='42501';
end;
$fn$;

create trigger ct02j_private_media_review_guard
before update on public.media_private_drafts
for each row execute function newsroom_private.guard_private_media_review();
revoke all on function newsroom_private.guard_private_media_review()
from public,anon,authenticated;

-- Supabase Storage COPY supports destinationBucket and requires SELECT on
-- private source + INSERT on the public destination. Only an active reviewer
-- who has already claimed one exact draft may write its fixed target key.
-- This DOES NOT grant generic public uploads into the approved/ prefix.
create policy ct02j_storage_approved_copy_insert
on storage.objects for insert to authenticated with check (
  bucket_id='media'
  and owner_id=(select auth.uid())::text
  and newsroom_private.has_staff_permission('media.approve')
  and newsroom_private.has_staff_permission('media.upload')
  and newsroom_private.has_staff_permission('media.edit_all')
  and exists (
    select 1 from public.media_private_drafts d
    where d.publication_path=name
      and d.state='publishing'
      and d.reviewed_by=(select auth.uid())
      and d.source_sha256 is not null
  )
);

-- All original public media images, URL paths and ownerless objects remain
-- untouched. Neither table approval nor Storage copy automatically updates
-- a published story's chosen featured_image_id.
commit;
